class BscException(Exception):
    """Main exception for hran_bsc library."""


class IncorrectState(BscException):
    """Exception is thrown when object state is incorrect"""


class LackOfResources(BscException):
    """Bss-system working on task in background and cannot take next operation on the same object"""


class NoMatchingAlarms(BscException):
    """No active or historical alarms exist in output"""


class ResetAborted(BscException):
    """Raised when reset bcf cannot be performed"""


class TimeLimitExceeded(BscException):
    """BSC connection problem with BCF. BSC cannot get information from BCF"""
